/**
 * Avatar sticker set — the Y2K stickers a person can wear as their avatar.
 *
 * The catalog (id / pack / R2 url) is generated by scripts/seed-avatar-stickers.ts
 * into ./avatar-sticker-catalog. Choosing a sticker stores its `url` in
 * users.image, exactly like an uploaded photo, so it renders on every surface
 * (web, desktop, phones) with no sticker-aware code and rides the same
 * cache-locally-refetch-on-change path covers already use.
 */

import {
  AVATAR_STICKERS,
  type AvatarSticker,
  type AvatarStickerPack,
} from "./avatar-sticker-catalog";

export { AVATAR_STICKERS };
export type { AvatarSticker, AvatarStickerPack };

/** Packs in display order + the picker's tab labels. */
export const AVATAR_STICKER_PACKS: { id: AvatarStickerPack; label: string }[] = [
  { id: "bright", label: "Bright" },
  { id: "tech", label: "Tech" },
  { id: "warm", label: "Warm" },
];

/** The curated row shown before ALL is opened — a spread across the three packs. */
export const FEATURED_STICKER_IDS: readonly string[] = [
  "bright-01",
  "bright-03",
  "bright-05",
  "tech-01",
  "tech-03",
  "tech-10",
  "warm-06",
  "warm-16",
];

const BY_ID = new Map(AVATAR_STICKERS.map((s) => [s.id, s]));

export function stickerById(id: string): AvatarSticker | undefined {
  return BY_ID.get(id);
}

export function featuredStickers(): AvatarSticker[] {
  return FEATURED_STICKER_IDS.map((id) => BY_ID.get(id)).filter(
    (s): s is AvatarSticker => Boolean(s),
  );
}

export function stickersByPack(pack: AvatarStickerPack): AvatarSticker[] {
  return AVATAR_STICKERS.filter((s) => s.pack === pack);
}

/** True when a users.image URL is one of our hosted stickers (base-agnostic,
 *  so it survives an R2_PUBLIC_URL change). Used to light the right chip. */
export function isStickerUrl(url: string | null | undefined): boolean {
  return Boolean(url && url.includes("/avatars/stickers/"));
}

/** A random sticker's URL — the once-at-signup default avatar. */
export function randomStickerUrl(): string {
  const pick = AVATAR_STICKERS[Math.floor(Math.random() * AVATAR_STICKERS.length)]!;
  return pick.url;
}
